var CATEGORY_LABELS = { weapon: "Weapon", armor: "Armor", shield: "Shield", ammo: "Ammunition", gear: "Adventuring gear", tool: "Tool", focus: "Spellcasting focus", trinket: "Magic trinket", magic: "Magic item" };
